const timestampMs = (value: string | null | undefined) => {
  if (!value) return null;
  const parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? parsed : null;
};

const isRecentTimestamp = (value: string | null | undefined, nowMs: number, staleMs: number) => {
  const parsed = timestampMs(value);
  return parsed !== null && nowMs - parsed >= 0 && nowMs - parsed <= staleMs;
};

const cameraFeedOnline = (feed: LiveCameraFeed, nowMs: number, loadedAtMs?: number | null) => {
  const status = String(feed.lastFrameStatus ?? '').trim().toLowerCase();
  const hasRecentMetadata = isRecentTimestamp(feed.lastFrameAt, nowMs, LIVE_FRAME_STALE_MS);
  const hasRecentLoadedFrame = typeof loadedAtMs === 'number' && nowMs - loadedAtMs >= 0 && nowMs - loadedAtMs <= LIVE_FRAME_LOAD_STALE_MS;
  if (['error', 'failed', 'offline', 'inactive'].includes(status)) return hasRecentLoadedFrame;
  return hasRecentMetadata || hasRecentLoadedFrame;
};

const formatTimeOnly = (value: string | null | undefined) => {
  const parsed = timestampMs(value);
  if (parsed === null) return null;
  return new Date(parsed).toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
};

const formatTimeWithMilliseconds = (value: string | null | undefined) => {
  const parsed = timestampMs(value);
  if (parsed === null) return null;
  const date = new Date(parsed);
  const time = date.toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  return `${time}.${String(date.getMilliseconds()).padStart(3, '0')}`;
};

