  String(value ?? 'camera')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 80) || 'camera';

const trainingArchiveFileName = (prompt: TrainingExportPrompt) => {
  const stamp = new Date(prompt.completedAt ?? Date.now()).toISOString().replace(/[:.]/g, '-');
  return `aql-training-${safeArchivePart(prompt.cameraCode ?? prompt.cameraName)}-${stamp}.zip`;
};

const buildTrainingShareText = (dataset: LiveTrainingDatasetExport, prompt: TrainingExportPrompt) => {
  const title = prompt.cameraName ?? prompt.cameraCode ?? 'camara';
  const urls = dataset.images.slice(0, 15).map((image) => image.url);
  const remaining = dataset.images.length - urls.length;
  return [
    `AQL Vision - recolha de treino ${title}`,
    `${dataset.images.length} imagens em ${dataset.folderPath ?? prompt.folderPath ?? 'Supabase Storage'}.`,
    ...urls,
    remaining > 0 ? `Mais ${remaining} imagens disponiveis na pasta Supabase.` : ''
  ].filter(Boolean).join('\n');
};

const copyTextToClipboard = async (text: string) => {
  if (navigator.clipboard && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
    return;
  }

  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.position = 'fixed';
  textArea.style.left = '-9999px';
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  document.execCommand('copy');
  textArea.remove();
};

