const formatClock = (seconds: number) => {
  const safeSeconds = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(safeSeconds / 60);
  const remainder = safeSeconds % 60;
  return `${String(minutes).padStart(2, '0')}:${String(remainder).padStart(2, '0')}`;
};

const pulse = (time: number, start: number, end: number) => {
  if (time < start || time > end) return 0;
  return Math.sin(((time - start) / (end - start)) * Math.PI);
};

const levelTone = (level: AlertLevel) => {
  if (level === 'critical') return 'border-red-300 bg-red-50 text-red-800 dark:border-red-500/40 dark:bg-red-500/12 dark:text-red-100';
  if (level === 'attention') return 'border-amber-300 bg-amber-50 text-amber-800 dark:border-amber-500/40 dark:bg-amber-500/12 dark:text-amber-100';
  return 'border-emerald-300 bg-emerald-50 text-emerald-800 dark:border-emerald-500/35 dark:bg-emerald-500/10 dark:text-emerald-100';
};

const metricLevel = (key: MetricKey, value: number): AlertLevel => {
  if (key === 'temperature') {
    if (value < 11 || value > 23) return 'critical';
    if (value < 14 || value > 18) return 'attention';
    return 'normal';
  }
  if (key === 'ph') {
    if (value < 7.6 || value > 8.4) return 'critical';
    if (value < 7.9 || value > 8.2) return 'attention';
    return 'normal';
  }
  if (key === 'oxygen') {
    if (value < 4) return 'critical';
    if (value < 6) return 'attention';
    return 'normal';
  }
  if (value < 25 || value > 35) return 'critical';
  if (value < 28 || value > 33) return 'attention';
  return 'normal';
};

const buildTelemetry = (time: number, injection: Injection | null) => {
  const thermalPulse = pulse(time, 24, 36);
  const oxygenPulse = pulse(time, 42, 55);
  const phPulse = pulse(time, 57, 67);

  const injectedThermal = injection === 'thermal' ? 4.8 : 0;
  const injectedOxygen = injection === 'oxygen' ? 2.6 : 0;

  const temperature = 16.1 + Math.sin(time / 5.5) * 0.32 + Math.sin(time / 2.8) * 0.14 + thermalPulse * 3.15 + injectedThermal;
  const ph = 7.98 + Math.sin(time / 7.2) * 0.04 + phPulse * 0.34;
  const oxygen = 6.85 + Math.cos(time / 6.3) * 0.22 - oxygenPulse * 2.05 - injectedOxygen;
  const salinity = 30.5 + Math.sin(time / 10) * 0.35;

  return {
    temperature: Number(temperature.toFixed(2)),
    ph: Number(ph.toFixed(3)),
    oxygen: Number(Math.max(1.8, oxygen).toFixed(2)),
    salinity: Number(salinity.toFixed(2))
  };
};

