const nowMinus = (minutes: number) => new Date(Date.now() - minutes * 60_000).toISOString();

export const getDemoAssetUrl = (fileName: string) => {
  const safeFileName = String(fileName || '')
    .replace(/\\/g, '/')
    .split('/')
    .filter(Boolean)
    .pop();

  if (!safeFileName) return '';

  if (typeof window !== 'undefined') {
    const desktopUrl = window.aqlDesktop?.demoAssetUrl?.(safeFileName);
    if (desktopUrl) return desktopUrl;
  }

  // Use root-relative path so the URL is correct regardless of SPA router depth.
  // base: "./" in vite.config produces relative URLs that break when the router
  // has navigated to a sub-path (e.g. /dashboard → ./demo/ resolves wrongly).
  return `/demo/${encodeURIComponent(safeFileName)}`;
};

