const round = (value: number, decimals = 1) => Number(value.toFixed(decimals));

const demoClamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const demoNoise = (index: number, seed: number) => {
  const value = Math.sin(index * 12.9898 + seed * 78.233) * 43758.5453123;
  return value - Math.floor(value);
};

const demoDateDaysAgo = (daysAgo: number) => {
  const date = new Date();
  date.setUTCHours(12, 0, 0, 0);
  date.setUTCDate(date.getUTCDate() - daysAgo);
  return date.toISOString().slice(0, 10);
};

const demoIsoMinutesAgo = (minutesAgo: number) => new Date(Date.now() - minutesAgo * 60_000).toISOString();

export const getDemoMonitoringEstimate = (timeSeconds = (Date.now() / 1000) % DEMO_VIDEO_DURATION_SECONDS): DemoMonitoringEstimate => {
  const schooling = Math.sin(timeSeconds / 12.4) * 4 + Math.cos(timeSeconds / 7.8) * 2;
  const micro = Math.sin(timeSeconds / 2.9) * 1.2 + Math.cos(timeSeconds / 1.7) * 0.8;
  const cameraCount = Math.max(14, Math.min(28, Math.round(20 + schooling + micro)));
  const usCycle = Math.sin(timeSeconds / 15.7) * 3.2 + Math.cos(timeSeconds / 8.4) * 1.8;
  const ultrasoundCount = Math.max(13, Math.min(32, Math.round(22 + usCycle)));
  const fusedCount = Math.round(cameraCount * 0.55 + ultrasoundCount * 0.45);
  const agreementPenalty = Math.min(6, Math.abs(cameraCount - ultrasoundCount));
  const confidence = Math.max(0.84, Math.min(0.97, (88 + Math.sin(timeSeconds / 8.3) * 5 - agreementPenalty) / 100));
  return { timeSeconds, cameraCount, ultrasoundCount, fusedCount, confidence };
};

