const estimateWeight = (lengthMm: number) => round(0.000022 * lengthMm ** 3, 2);

const buildDemoGrowthSeries = (monitoring: DemoMonitoringEstimate): AqlGrowthDashboardPoint[] => {
  const totalDays = 91;
  return Array.from({ length: totalDays }).map((_, index) => {
    const daysAgo = totalDays - index - 1;
    const age = index;
    const liveLift = daysAgo === 0 ? Math.sin(monitoring.timeSeconds / 9) * 0.24 : 0;
    const median = 214.8 + age * 0.36 + Math.sin(age / 8.5) * 1.15 + liveLift;
    const spread = 15.2 - Math.min(5.2, age * 0.045) + Math.sin(age / 12) * 0.7;
    const avg = median + 1.1 + Math.sin(age / 6.4) * 0.55;
    const sampleBase = 330 + monitoring.fusedCount * 5 + Math.sin(age / 5.2) * 32 + demoNoise(index, 4) * 34;
    const sampleCount = Math.round(sampleBase + (daysAgo === 0 ? monitoring.fusedCount * 2 : 0));
    const rejectedCount = Math.max(8, Math.round(sampleCount * (0.035 + demoNoise(index, 8) * 0.025)));
    const confidence = demoClamp(monitoring.confidence + Math.sin(age / 10) * 0.015 + demoNoise(index, 12) * 0.018, 0.86, 0.97);
    const uniformity = demoClamp(0.74 + age * 0.0012 + Math.sin(age / 13) * 0.025 - demoNoise(index, 18) * 0.012, 0.72, 0.88);
    const warningLevel =
      Math.abs(monitoring.cameraCount - monitoring.ultrasoundCount) >= 5 && daysAgo === 0
        ? 'warning'
        : index === 67
          ? 'warning'
          : 'normal';

    return {
      cohort_id: DEMO_GROWTH_COHORT_ID,
      zone_id: DEMO_GROWTH_ZONE_ID,
      period_start: demoDateDaysAgo(daysAgo),
      period_end: null,
      median_size: round(median, 1),
      avg_size: round(avg, 1),
      p10_size: round(median - spread * 1.45, 1),
      p25_size: round(median - spread * 0.55, 1),
      p75_size: round(median + spread * 0.62, 1),
      p90_size: round(median + spread * 1.55, 1),
      sample_count: sampleCount,
      rejected_count: rejectedCount,
      confidence: round(confidence, 3),
      uniformity_score: round(uniformity, 3),
      warning_level: warningLevel,
      has_enough_sample: sampleCount >= 180
    };
  });
};

const buildDemoMeasurements = (latestMedian: number, monitoring: DemoMonitoringEstimate): AqlGrowthMeasurement[] => {
  const totalRows = Math.max(300, Math.min(520, 250 + monitoring.fusedCount * 9));
  return Array.from({ length: totalRows }).map((_, index) => {
    const confidence = demoClamp(0.76 + demoNoise(index, 21) * 0.22 - (index % 47 === 0 ? 0.25 : 0), 0.35, 0.98);
    const isOutlier = index % 83 === 0 || index % 137 === 0;
    const echoOverlap = index % 59 === 0;
    const partialBody = index % 71 === 0;
    const isValid = confidence >= 0.6 && !echoOverlap && !partialBody;
    const distribution = (demoNoise(index, 31) + demoNoise(index, 37) + demoNoise(index, 43) - 1.5) * 14.5;
    const length = latestMedian + distribution + Math.sin(index / 11) * 3.2 + (isOutlier ? 24 + demoNoise(index, 49) * 11 : 0);
    const width = length * (0.47 + demoNoise(index, 53) * 0.055);
    const area = length * width * (0.74 + demoNoise(index, 57) * 0.08);
    const measuredAt = demoIsoMinutesAgo(index * 2.2 + demoNoise(index, 61) * 1.7);
    const captureSlot = Math.floor(index / Math.max(1, Math.round(totalRows / 8)));
    const rejectionReason = isValid
      ? null
      : confidence < 0.6
        ? 'low_confidence'
        : echoOverlap
          ? 'ultrasound_echo_overlap'
          : 'partial_body';

    return {
      id: `demo-growth-measurement-${index + 1}`,
      cohort_id: DEMO_GROWTH_COHORT_ID,
      zone_id: DEMO_GROWTH_ZONE_ID,
      camera_id: 'CAM-04',
      capture_id: `demo-growth-capture-${Math.min(8, captureSlot + 1)}`,
      detection_id: `demo-video-us-detection-${index + 1}`,
      measured_at: measuredAt,
      length_mm: round(length, 1),
      width_mm: round(width, 1),
      area_mm2: round(area, 0),
      estimated_weight_g: estimateWeight(length),
      detection_confidence: round(confidence, 3),
      measurement_quality: round(isValid ? demoClamp(confidence - 0.035 + demoNoise(index, 67) * 0.04, 0.68, 0.98) : confidence * 0.65, 3),
      is_valid: isValid,
      rejection_reason: rejectionReason,
      created_at: measuredAt
    };
  });
};

