const filterDemoSeriesByRange = (series: AqlGrowthDashboardPoint[], filters?: Partial<GrowthFilters>) => {
  const from = filters?.fromDate ? new Date(`${filters.fromDate}T00:00:00.000Z`).getTime() : Number.NEGATIVE_INFINITY;
  const to = filters?.toDate ? new Date(`${filters.toDate}T23:59:59.999Z`).getTime() : Number.POSITIVE_INFINITY;
  return series.filter((point) => {
    const time = new Date(`${point.period_start.slice(0, 10)}T12:00:00.000Z`).getTime();
    return time >= from && time <= to;
  });
};

export const getDemoGrowthDataset = (filters?: Partial<GrowthFilters>): DemoGrowthDataset => {
  const options = demoGrowthOptions();
  const selectionMatches =
    (!filters?.clientId || filters.clientId === DEMO_GROWTH_CLIENT_ID) &&
    (!filters?.projectId || filters.projectId === DEMO_GROWTH_PROJECT_ID) &&
    (!filters?.locationId || filters.locationId === DEMO_GROWTH_LOCATION_ID) &&
    (!filters?.zoneId || filters.zoneId === DEMO_GROWTH_ZONE_ID) &&
    (!filters?.cohortId || filters.cohortId === DEMO_GROWTH_COHORT_ID) &&
    (!filters?.speciesId || filters.speciesId === DEMO_GROWTH_SPECIES_ID) &&
    (!filters?.phaseId || filters.phaseId === DEMO_GROWTH_PHASE_ID);

  if (!selectionMatches) {
    return {
      ...options,
      series: [],
      latestDayMeasurements: [],
      recentMeasurements: [],
      captures: [],
      calibration: null
    };
  }

  const monitoring = getDemoMonitoringEstimate();
  const series = filterDemoSeriesByRange(buildDemoGrowthSeries(monitoring), filters);
  const latestMedian = (series.length ? series[series.length - 1].median_size : null) ?? 247.4;
  const latestDayMeasurements = buildDemoMeasurements(latestMedian, monitoring);

  return {
    ...options,
    series,
    latestDayMeasurements,
    recentMeasurements: latestDayMeasurements.slice(0, 250),
    captures: buildDemoCaptures(latestMedian, monitoring),
    calibration: buildDemoCalibration()
  };
};

