const readOverrides = (): Record<string, DemoAlertOverride> => {
  if (typeof window === 'undefined') return {};
  try {
    const raw = window.localStorage.getItem(DEMO_ALERT_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
};

const writeOverrides = (overrides: Record<string, DemoAlertOverride>) => {
  if (typeof window === 'undefined') return;
  window.localStorage.setItem(DEMO_ALERT_STORAGE_KEY, JSON.stringify(overrides));
};

export const getDemoVisionAlerts = () => {
  const overrides = readOverrides();
  return baseDemoAlerts()
    .map((alert) => {
      const override = overrides[alert.case_id ?? alert.id] ?? {};
      return {
        ...alert,
        ...override,
        metadata: {
          ...alert.metadata,
          ...(override.metadata ?? {})
        }
      };
    })
    .filter((alert) => !(overrides[alert.case_id ?? alert.id]?.hidden))
    .sort((a, b) => new Date(b.detected_at ?? b.createdAt).getTime() - new Date(a.detected_at ?? a.createdAt).getTime());
};

export const saveDemoAlertValidation = (
  caseId: string,
  patch: Pick<DemoAlertOverride, 'status' | 'validation_result' | 'anomaly_type' | 'severity' | 'validation_notes' | 'validated_at' | 'validatedByEmail'>
) => {
  const overrides = readOverrides();
  overrides[caseId] = {
    ...(overrides[caseId] ?? {}),
    ...patch,
    updatedAt: new Date().toISOString()
  };
  writeOverrides(overrides);
};

export const hideDemoAlert = (caseId: string) => {
  const overrides = readOverrides();
  overrides[caseId] = {
    ...(overrides[caseId] ?? {}),
    hidden: true,
    updatedAt: new Date().toISOString()
  };
  writeOverrides(overrides);
};

export const getDemoDashboardSummary = (alerts: RawVisionAlert[]): MvpDashboardSummary => {
  const pendingValidation = alerts.filter((alert) => String(alert.status ?? '').toLowerCase() === 'pending').length;
  const activeAlerts = alerts.filter((alert) => !['confirmed', 'rejected', 'resolved'].includes(String(alert.status ?? '').toLowerCase())).length;
  const latest = alerts[0] ?? null;
  const latestVisualCapture = alerts.find((alert) => {
    const status = String(alert.metadata?.detection_status ?? '').toLowerCase();
    const type = String(alert.alert_type ?? alert.problemName ?? '').toLowerCase();
    return status.includes('peixe') || type.includes('visual');
  }) ?? latest;
  const latestCaptureAlertId = latestVisualCapture
    ? String(latestVisualCapture.case_id ?? latestVisualCapture.id ?? latestVisualCapture.alert_id ?? '')
    : null;
  const oxygen = Number(latest?.metadata?.oxygen ?? 5.8);
  const temperature = Number(latest?.metadata?.temperature ?? 17.2);
  const ph = Number(latest?.metadata?.ph ?? 8.08);
  const demoVideoSources = getDemoVideoSources();

  return {
    kitId: 'AQL-DEMO-KIT-04',
    status: activeAlerts > 0 ? 'Atenção' : 'OK',
    reason: activeAlerts > 0 ? `${activeAlerts} ${activeAlerts === 1 ? 'alerta em validação' : 'alertas em validação'}` : 'Demo sem alertas pendentes',
    updatedAt: new Date().toISOString(),
    latestCapture: latestVisualCapture ? {
      imageUrl: latestVisualCapture.imageUrl ?? latestVisualCapture.image_url ?? null,
      videoMp4Url: demoVideoSources.mp4,
      videoWebmUrl: demoVideoSources.webm,
      videoStartSeconds: getDemoDetectionTime(latestCaptureAlertId),
      videoLoop: true,
      alertId: latestCaptureAlertId,
      capturedAt: latestVisualCapture.detected_at ?? latestVisualCapture.createdAt,
      tank: 'T-04',
      phase: 'adult',
      species: 'Pregado',
      detectionStatus: latestVisualCapture.metadata?.detection_status ?? null
    } : null,
    alertsActive: activeAlerts,
    pendingValidation,
    sensors: {
      temperature,
      ph,
      oxygen,
      salinity: Number(latest?.metadata?.salinity ?? 30.5),
      status: oxygen < 6 || temperature < 18 || temperature > 22 || ph < 7 || ph > 8.2 ? 'Atenção' : 'OK'
    },
    device: {
      online: true,
      lastCommunication: new Date(Date.now() - 7000).toISOString(),
      batteryPercent: 94,
      communicationAt: new Date(Date.now() - 7000).toISOString(),
      cameraOk: true,
      sensorsOk: true
    }
  };
};
