  const MENU_ORDER_STORAGE_KEY = 'aql_vision_sidebar_menu_order';
  const MENU_HIDDEN_STORAGE_KEY = 'aql_vision_sidebar_menu_hidden';
  const MENU_ORDER_EVENT = 'aql-vision-menu-order-changed';
  const DEFAULT_MENU_ORDER: MainView[] = ['operations', 'clinical', 'sensors', 'growth', 'live', 'analytics'];

  const normalizeMenuOrder = (value: unknown): MainView[] => {
    const parsed = Array.isArray(value) ? value : [];
    const valid = parsed.filter((item): item is MainView =>
      DEFAULT_MENU_ORDER.includes(item as MainView)
    );
    return [...valid, ...DEFAULT_MENU_ORDER.filter((item) => !valid.includes(item))];
  };

  const readMenuOrderPreference = (): MainView[] => {
    if (typeof window === 'undefined') return [...DEFAULT_MENU_ORDER];
    try {
      return normalizeMenuOrder(JSON.parse(window.localStorage.getItem(MENU_ORDER_STORAGE_KEY) ?? '[]'));
    } catch {
      return [...DEFAULT_MENU_ORDER];
    }
  };

  const normalizeHiddenMenuItems = (value: unknown): MainView[] => {
    const parsed = Array.isArray(value) ? value : [];
    const valid = Array.from(new Set(parsed.filter((item): item is MainView =>
      DEFAULT_MENU_ORDER.includes(item as MainView)
    )));
    return valid.length >= DEFAULT_MENU_ORDER.length ? [] : valid;
  };

  const readHiddenMenuPreference = (): MainView[] => {
    if (typeof window === 'undefined') return [];
    try {
      return normalizeHiddenMenuItems(JSON.parse(window.localStorage.getItem(MENU_HIDDEN_STORAGE_KEY) ?? '[]'));
    } catch {
      return [];
    }
  };

  const orderSectionItems = (items: SectionItem[], order: MainView[], hiddenItems: MainView[]) => {
    const itemMap = new Map(items.map((item) => [item.id, item]));
    return [
      ...order.map((id) => itemMap.get(id)).filter(Boolean),
      ...items.filter((item) => !order.includes(item.id))
    ].filter((item) => item && !hiddenItems.includes(item.id)) as SectionItem[];
  };
