  const sensorTypeFromAlertCase = (item: { rawAlert?: RawVisionAlert | null }) =>
    getAlertSensorType(item.rawAlert);

  const isSensorAlertCase = (item: { rawAlert?: RawVisionAlert | null }) => Boolean(sensorTypeFromAlertCase(item));

  const matchesAlertTypeFilter = (item: { rawAlert?: RawVisionAlert | null; image?: string }, filter: AlertTypeFilter) => {
    if (filter === 'all') return true;
    const sensorType = sensorTypeFromAlertCase(item);
    if (filter === 'sensor') return Boolean(sensorType);
    if (filter === 'visual') return hasVisualEvidence(item.rawAlert) || Boolean(item.image);
    return sensorType === filter;
  };
  const slugify = (value: string) =>
    value
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');

  const slugSegments = (value: unknown) =>
    String(value ?? '')
      .split(/[/?#]+/)
      .map((segment) => slugify(segment))
      .filter(Boolean);

  const projectMatchesRoute = (row: any, routeProjectSlug: string, routeClientSlug: string) => {
    const rawSlug = String(row.slug ?? '');
    const slugParts = slugSegments(rawSlug);
    const directSlug = slugify(rawSlug);
    const nameSlug = slugify(String(row.name ?? ''));

    return (
      directSlug === routeProjectSlug ||
      directSlug === `${routeClientSlug}-${routeProjectSlug}` ||
      slugParts[slugParts.length - 1] === routeProjectSlug ||
      (slugParts[0] === routeClientSlug && slugParts[slugParts.length - 1] === routeProjectSlug) ||
      nameSlug === routeProjectSlug
    );
  };

