  const uniqueSorted = (values: Array<string | null | undefined>) =>
    Array.from(new Set(values.map((value) => String(value ?? '').trim()).filter(Boolean))).sort((a, b) => a.localeCompare(b));

  const scopeLabelKey = (value: unknown) => slugify(String(value ?? ''));

  const isTechnicalTemperatureAlias = (value: unknown) => {
    const normalized = String(value ?? '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
    return /^(temp|temperatura|temperature)(_(temp|temperatura|temperature))*$/.test(normalized);
  };

  const isInternalIdentifier = (value: unknown) => {
    const text = String(value ?? '').trim();
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)
      || /^[0-9a-f]{12,}$/i.test(text);
  };

  const readableAlertLabel = (...values: unknown[]) =>
    values
      .map((value) => String(value ?? '').trim())
      .find((value) => value && !isInternalIdentifier(value)) ?? null;

  const formatAlertNumber = (value: unknown) => {
    if (value === null || value === undefined || value === '') return null;
    const numeric = Number(value);
    if (Number.isFinite(numeric)) {
      return Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(2).replace(/\.?0+$/, '');
    }
    return readableAlertLabel(value);
  };

  const formatAlertUnit = (value: unknown) => {
    const unit = String(value ?? '').trim();
    if (!unit) return '';
    if (/^(c|celsius|ºc|°c)$/i.test(unit)) return ' °C';
    if (/^(mg_l|mg\/l)$/i.test(unit)) return ' mg/L';
    return ` ${unit}`;
  };

