        const timestamp = readDateValue(row) ?? new Date().toISOString();
        const config = SENSOR_LIMITS[metric];
        const unit = pickString(row, ['unit']) ?? pickString(metadata, ['unit']) ?? pickString(sensor, ['unit']) ?? config.unit;
        const target = config.max === null
