// 🛠️ HELPER: Obter idioma atual (Síncrono)
export function getCurrentLanguage(): Language {
  if (typeof window !== 'undefined') {
    const saved = localStorage.getItem('aql_language') as Language;
    if (saved && languages.some(l => l.code === saved)) return saved;
  }
  return 'pt';
}

// 🛠️ FUNÇÃO DE TRADUÇÃO (t)
export function t(category: string, keyOrLang?: string | Language | any, langOrParams?: Language | any, params?: any): string {
  let realKey: string;
  let targetLang: Language;
  let realParams: any;

  // Handle t('category.key', lang, params)
  if (category.includes('.') && (keyOrLang === undefined || typeof keyOrLang === 'string')) {
    const [cat, k] = category.split('.');
    realKey = k;
    category = cat;
    targetLang = (typeof keyOrLang === 'string' && ['pt','en','fr','es','de'].includes(keyOrLang)) ? (keyOrLang as Language) : getCurrentLanguage();
    realParams = langOrParams;
  } else {
    // Handle t('category', 'key', lang, params)
    realKey = keyOrLang as string;
    targetLang = (typeof langOrParams === 'string' && ['pt','en','fr','es','de'].includes(langOrParams)) ? (langOrParams as Language) : getCurrentLanguage();
    realParams = params || (typeof langOrParams === 'object' ? langOrParams : undefined);
  }

  try {
    let categoryObj = (translations as any)[category];
    
    // Fallback search if category is not found (some legacy components use keys without category)
    if (!categoryObj) {
      // Search in all categories
      for (const cat in translations) {
        if ((translations as any)[cat][realKey || category]) {
          categoryObj = (translations as any)[cat];
          if (!realKey) realKey = category;
          break;
        }
      }
    }

    if (!categoryObj) return realKey || category;
    const keyObj = categoryObj[realKey];
    if (!keyObj) return realKey;
    
    let text = keyObj[targetLang] || keyObj['pt'] || realKey;
    
    // Simple template replacement: {email} -> params.email
    if (realParams) {
      Object.keys(realParams).forEach(p => {
        text = text.replace(new RegExp(`{${p}}`, 'g'), String(realParams[p]));
      });
    }
    return text;
  } catch (e) {
    return realKey || category;
  }
}

// 🎣 HOOK PARA IDIOMA ATUAL (Reativo)
export function useLanguage() {
  const [lang, setLang] = useState<Language>(getCurrentLanguage());

  useEffect(() => {
    const handleStorageChange = () => {
      setLang(getCurrentLanguage());
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  return lang;
}

// 🔧 FUNÇÃO PARA MUDAR IDIOMA
export function setLanguage(lang: Language) {
  localStorage.setItem('aql_language', lang);
  window.dispatchEvent(new Event('storage'));
  // Emit custom event for components using specific listeners
  window.dispatchEvent(new CustomEvent('languageChange', { detail: lang }));
}
