import { ShieldCheck, Settings2, X } from 'lucide-react';
import { Switch } from './ui/switch';

export type CookiePreferencesState = {
  necessary: boolean;
  preferences: boolean;
  analytics: boolean;
  consentedAt: string;
  version: number;
};

export const COOKIE_PREFERENCES_KEY = 'aql-cookie-preferences-v1';

export const defaultCookiePreferences = (): CookiePreferencesState => ({
  necessary: true,
  preferences: true,
  analytics: false,
  consentedAt: new Date().toISOString(),
  version: 1
});

export const readCookiePreferences = (): CookiePreferencesState | null => {
  if (typeof window === 'undefined') return null;
  const raw = window.localStorage.getItem(COOKIE_PREFERENCES_KEY);
  if (!raw) return null;

  try {
    const parsed = JSON.parse(raw) as CookiePreferencesState;
    if (typeof parsed?.necessary !== 'boolean') return null;
    return parsed;
  } catch {
    return null;
  }
};

export const saveCookiePreferences = (preferences: CookiePreferencesState) => {
  if (typeof window === 'undefined') return;
  window.localStorage.setItem(COOKIE_PREFERENCES_KEY, JSON.stringify(preferences));
};

