export async function fetchCameraTrainingDataset(params: {
  cameraId?: string | null;
  cameraCode?: string | null;
}): Promise<LiveTrainingDatasetExport> {
  const body = {
    camera_id: params.cameraId ?? null,
    camera_code: params.cameraCode ?? null
  };
  const { data, error } = await supabase.functions.invoke('vision-captures/training-export', { body });
  if (error) {
    let detail = error.message;
    const context = (error as { context?: unknown }).context;
    if (context) {
      const parsed = await readFunctionErrorContext(context);
      detail = parsed.message ? `${parsed.status ?? ''}: ${parsed.message}`.trim() : parsed.status ? `${parsed.status}: ${detail}` : detail;
    }
    throw new Error(detail);
  }

  const payload = asRecord(data);
  if (payload.error) throw new Error(String(payload.error));

  const images = Array.isArray(payload.images)
    ? payload.images
      .map((item) => {
        const row = asRecord(item);
        const name = firstString(row, ['name']) ?? '';
        const path = firstString(row, ['path']) ?? '';
        const url = firstString(row, ['url', 'publicUrl', 'public_url']) ?? (path ? publicCaptureUrl(path) : '');
        if (!name || !path || !url) return null;
        return {
          name,
          path,
          url,
          size: firstNumber(row, ['size']),
          contentType: firstString(row, ['contentType', 'content_type', 'mimetype']),
          createdAt: firstString(row, ['createdAt', 'created_at']),
          updatedAt: firstString(row, ['updatedAt', 'updated_at'])
        } satisfies LiveTrainingDatasetImage;
      })
      .filter(Boolean) as LiveTrainingDatasetImage[]
    : [];

  return {
    bucket: firstString(payload, ['bucket']) ?? 'captures',
    folderPath: firstString(payload, ['folderPath', 'folder_path']) ?? null,
    imageCount: firstNumber(payload, ['imageCount', 'image_count']) ?? images.length,
    totalFolderImageCount: firstNumber(payload, ['totalFolderImageCount', 'total_folder_image_count']) ?? images.length,
    training: trainingStateFromPayload(payload.training),
    images
  };
}

export async function fetchLatestCapture(params: {
  zoneId?: string;
  clientId?: string;
  projectId?: string;
}): Promise<LiveCapture | null> {
  if (!params.zoneId && !params.clientId) return null;

  const deviceIds = await fetchScopedDeviceIds({
    zoneId: params.zoneId,
    clientId: params.clientId,
    projectId: params.projectId,
    preferredTypes: ['camera']
  });
  if (deviceIds.length === 0) return null;

  let query = supabase
    .from('aql_vision_captures')
    .select('*')
    .in('device_id', deviceIds)
    .order('timestamp', { ascending: false })
    .limit(1);

  const result = await query;
  const rows = handleQueryError<Record<string, unknown>[]>({ data: result.data, error: result.error }, 'Failed to load latest capture') ?? [];
  const row = rows[0];
  if (!row) return null;

  return {
    id: String(row.capture_id ?? row.id ?? ''),
    zone_id: params.zoneId ?? firstString(row, ['zone_id', 'tank_id']),
    image_url: firstString(row, ['image_url', 'imageUrl', 'image_path', 'storage_path', 'url']),
    captured_at: String(row.timestamp ?? row.created_at ?? new Date().toISOString()),
    species: firstString(row, ['species']),
    phase: firstString(row, ['biological_phase', 'phase'])
  };
}

export async function fetchLatestSensorReading(params: {
  zoneId?: string;
  clientId?: string;
  projectId?: string;
}): Promise<LiveSensorReading | null> {
  if (!params.zoneId && !params.clientId) return null;

  const deviceIds = await fetchScopedDeviceIds({
    zoneId: params.zoneId,
    clientId: params.clientId,
    projectId: params.projectId,
    preferredTypes: ['sensor']
  });

  let scopedQuery = supabase
    .from('aql_sensor_readings')
    .select('*')
    .order('timestamp', { ascending: false })
    .limit(80);

  if (params.clientId) scopedQuery = scopedQuery.eq('client_id', params.clientId);

  const scopedResult = await scopedQuery;
  let rows = handleQueryError<Record<string, unknown>[]>({ data: scopedResult.data, error: scopedResult.error }, 'Failed to load sensor readings') ?? [];
  if (rows.length === 0 && deviceIds.length > 0) {
    const deviceResult = await supabase
      .from('aql_sensor_readings')
      .select('*')
      .in('device_id', deviceIds)
      .order('timestamp', { ascending: false })
      .limit(80);
    rows = handleQueryError<Record<string, unknown>[]>({ data: deviceResult.data, error: deviceResult.error }, 'Failed to load sensor readings by device') ?? [];
  }
  if (rows.length === 0) return null;

  const latest: LiveSensorReading = {
    zone_id: params.zoneId ?? null,
    temperature: null,
    ph: null,
    oxygen: null,
    salinity: null,
    recorded_at: String(rows[0].timestamp ?? rows[0].recorded_at ?? rows[0].created_at ?? new Date().toISOString())
  };

  rows.forEach((row) => {
    const metadata = asRecord(row.metadata);
    const source = { ...metadata, ...row };
    const combinedValues: Array<[keyof Pick<LiveSensorReading, 'temperature' | 'ph' | 'oxygen' | 'salinity'>, number | null]> = [
      ['temperature', firstNumber(source, ['temperature', 'temp', 'water_temperature', 'water_temperature_c', 'temperature_c', 'temp_c'])],
      ['ph', firstNumber(source, ['ph', 'pH'])],
      ['oxygen', firstNumber(source, ['oxygen', 'dissolved_oxygen', 'do_mg_l', 'oxygen_mg_l', 'o2'])],
      ['salinity', firstNumber(source, ['salinity', 'salinity_psu', 'psu'])]
    ];

    combinedValues.forEach(([metric, value]) => {
      if (latest[metric] === null && value !== null) latest[metric] = value;
    });

    const typedMetric = sensorMetricFor(row.sensor_type ?? metadata.sensor_type ?? metadata.type);
    const typedValue = firstNumber(source, ['value', 'last_value', 'reading']);
    if (typedMetric && latest[typedMetric] === null && typedValue !== null) {
      latest[typedMetric] = typedValue;
    }
  });

  return latest;
}

export async function fetchDetectionCount(captureId: string): Promise<number | null> {
  if (!captureId) return null;
  const result = await supabase
    .from('aql_detections')
    .select('detection_id', { count: 'exact', head: true })
    .eq('capture_id', captureId);

  if (result.error) {
    throw new Error(`Failed to load detections: ${result.error.message ?? result.error}`);
  }
  return result.count ?? null;
}
