type MobileTab = 'status' | 'alerts' | 'observe' | 'asset' | 'settings';
type SyncEventType = 'validate_alert' | 'field_observation';

type SyncEvent = {
  id: string;
  type: SyncEventType;
  createdAt: string;
  attempts: number;
  payload: Record<string, any>;
  lastError?: string;
};

type ObservationForm = {
  zoneId: string;
  category: string;
  severity: Severity;
  note: string;
};

const KV_STORE_TABLE = 'kv_store_113fe7c2';
const SESSION_TOKEN_KEYS = ['aql_auth_token', 'visionAlertsToken', 'sessionToken'];
const SESSION_EMAIL_KEYS = ['aql_user_email', 'visionAlertsEmail', 'userEmail'];
const MOBILE_SYNC_QUEUE_KEY = 'aql_mobile_sync_queue_v1';
const MOBILE_OBSERVATION_DRAFT_KEY = 'aql_mobile_observation_draft_v2';
const LOGIN_CLIENT_CONFIRMED_KEY = 'aql_login_client_confirmed_vision-alerts';

const severityOrder: Record<Severity, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3
};

const readStoredValue = (keys: string[]) => {
  for (const key of keys) {
    const value = localStorage.getItem(key);
    if (value) return value;
  }
  return null;
};

const parseJson = (value: unknown) => {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

const stringFrom = (value: unknown) => {
  const next = String(value ?? '').trim();
  return next || null;
};

const dateFrom = (value: unknown) => {
  const date = new Date(String(value ?? ''));
  return Number.isNaN(date.getTime()) ? null : date;
};

const formatShortTime = (value: unknown) => {
  const date = dateFrom(value);
  if (!date) return 'sem dados';
  return date.toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit' });
};

const formatRelative = (value: unknown) => {
  const date = dateFrom(value);
  if (!date) return 'sem dados';
  const minutes = Math.max(0, Math.round((Date.now() - date.getTime()) / 60000));
  if (minutes < 1) return 'agora';
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours} h`;
  return `${Math.round(hours / 24)} d`;
};

const nowIso = () => new Date().toISOString();

const newEventId = () => {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID();
  return `evt-${Date.now()}-${Math.random().toString(16).slice(2)}`;
};

const readSyncQueue = (): SyncEvent[] => {
  try {
    const raw = localStorage.getItem(MOBILE_SYNC_QUEUE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const writeSyncQueue = (queue: SyncEvent[]) => {
  localStorage.setItem(MOBILE_SYNC_QUEUE_KEY, JSON.stringify(queue));
};

const readObservationDraft = (): ObservationForm => {
  try {
    const raw = localStorage.getItem(MOBILE_OBSERVATION_DRAFT_KEY);
    if (raw) {
      const value = JSON.parse(raw);
      return {
        zoneId: String(value.zoneId ?? ''),
        category: String(value.category ?? 'observacao_campo'),
        severity: (value.severity as Severity) ?? 'medium',
        note: String(value.note ?? '')
      };
    }
  } catch {
    // Fall through to the default draft.
  }

  return { zoneId: '', category: 'observacao_campo', severity: 'medium', note: '' };
};

const sanitizeInput = (value: string, maxLength = 600) =>
  value
    .replace(/<[^>]*>/g, ' ')
    .replace(/[\u0000-\u001F\u007F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLength);

const parseResponsePayload = async (response: Response) => {
  const text = await response.text();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return { message: text };
  }
};

const normalizeRowToAlert = (row: Record<string, any>, fallbackPrefix: string): RawVisionAlert => {
  const metadata = row.metadata && typeof row.metadata === 'object' ? row.metadata : {};
  const createdAt = stringFrom(row.detected_at ?? row.detectedAt ?? row.created_at ?? row.createdAt ?? row.updated_at)
    ?? new Date().toISOString();
  const id = stringFrom(row.case_id ?? row.alert_id ?? row.id ?? row.key) ?? `${fallbackPrefix}-${createdAt}`;

  return {
    ...row,
    id,
    case_id: stringFrom(row.case_id) ?? undefined,
    alert_id: stringFrom(row.alert_id) ?? undefined,
    client_id: stringFrom(row.client_id ?? metadata.client_id) ?? undefined,
    imageUrl: stringFrom(row.image_url ?? row.imageUrl ?? metadata.image_url ?? metadata.imageUrl) ?? undefined,
    image_url: stringFrom(row.image_url ?? row.imageUrl ?? metadata.image_url ?? metadata.imageUrl) ?? undefined,
    species: stringFrom(row.species ?? metadata.species) ?? undefined,
    biological_phase: stringFrom(row.biological_phase ?? row.phase ?? metadata.biological_phase ?? metadata.phase) ?? undefined,
    detected_at: stringFrom(row.detected_at ?? row.detectedAt ?? row.created_at ?? row.createdAt) ?? undefined,
    model_confidence: row.model_confidence ?? row.confidence ?? metadata.model_confidence ?? metadata.confidence,
    alert_type: stringFrom(row.alert_type ?? row.alertType ?? row.type ?? metadata.alert_type ?? metadata.alertType) ?? undefined,
    severity: (stringFrom(row.severity ?? metadata.severity) as Severity | null) ?? undefined,
    status: row.status ?? metadata.status,
    problemName: stringFrom(row.problem_name ?? row.problemName ?? metadata.problem_name ?? metadata.problemName) ?? undefined,
    problemDescription: stringFrom(row.problem_description ?? row.problemDescription ?? metadata.problem_description ?? metadata.problemDescription) ?? undefined,
    metadata,
    createdAt,
    created_at: stringFrom(row.created_at) ?? undefined,
    updatedAt: stringFrom(row.updated_at ?? row.updatedAt) ?? undefined,
    validation_result: row.validation_result ?? row.validationResult,
    validation_notes: stringFrom(row.validation_notes ?? row.validationNotes ?? row.notes) ?? undefined
  };
};

const normalizeKvAlert = (row: Record<string, any>): RawVisionAlert | null => {
  const value = parseJson(row.value);
  if (!value || typeof value !== 'object') return null;
  return normalizeRowToAlert({ key: row.key, ...(value as Record<string, any>) }, 'kv-alert');
};

const applyScope = (query: any, clientId?: string | null, projectId?: string | null) => {
  let next = query;
  if (clientId) next = next.eq('client_id', clientId);
  if (projectId) next = next.eq('project_id', projectId);
  return next;
};

const loadProductionAlerts = async (scope?: { clientId?: string | null; projectId?: string | null }): Promise<RawVisionAlert[]> => {
  const [alertsResult, casesResult, kvResult] = await Promise.all([
    applyScope(supabase.from('aql_alerts').select('*'), scope?.clientId, scope?.projectId).order('created_at', { ascending: false }).limit(120),
    applyScope(supabase.from('aql_cases').select('*'), scope?.clientId, scope?.projectId).order('created_at', { ascending: false }).limit(120),
    supabase.from(KV_STORE_TABLE).select('key,value').ilike('key', 'visionAlert:%').limit(120)
  ]);

  const alerts = Array.isArray(alertsResult.data)
    ? alertsResult.data.map((row) => normalizeRowToAlert(row, 'alert'))
    : [];
  const cases = Array.isArray(casesResult.data)
    ? casesResult.data.map((row) => normalizeRowToAlert(row, 'case'))
    : [];
  const kvAlerts = Array.isArray(kvResult.data)
    ? kvResult.data.map(normalizeKvAlert).filter((item): item is RawVisionAlert => Boolean(item))
    : [];

  const byId = new Map<string, RawVisionAlert>();
  [...alerts, ...cases, ...kvAlerts].forEach((item) => byId.set(item.id, item));
  return Array.from(byId.values());
};

const summaryFromCases = (cases: ClinicalCase[]): MvpDashboardSummary => {
  const newest = [...cases].sort((a, b) => new Date(b.capturedAt).getTime() - new Date(a.capturedAt).getTime())[0] ?? null;
  const pending = cases.filter((item) => item.validationStatus === 'pending').length;
  const critical = cases.filter((item) => item.validationStatus === 'pending' && item.severity === 'critical').length;
  const high = cases.filter((item) => item.validationStatus === 'pending' && item.severity === 'high').length;
  const warningSensor =
    newest?.oxygen !== null && newest?.oxygen !== undefined && newest.oxygen < 5.5
      ? 'O2 baixo'
      : newest?.temperature !== null && newest?.temperature !== undefined && (newest.temperature < 16 || newest.temperature > 24)
        ? 'Temperatura fora'
        : newest?.ph !== null && newest?.ph !== undefined && (newest.ph < 7.2 || newest.ph > 8.4)
          ? 'pH fora'
          : 'OK';

  return {
    status: critical > 0 ? 'Alerta' : high > 0 || warningSensor !== 'OK' ? 'Atenção' : 'OK',
    reason: critical > 0 ? `${critical} alerta crítico por validar` : high > 0 ? `${high} alerta de alta prioridade` : 'Operação sem alertas críticos pendentes',
    updatedAt: newest?.capturedAt ?? new Date().toISOString(),
    latestCapture: newest ? {
      alertId: newest.id,
      imageUrl: newest.image || null,
      capturedAt: newest.capturedAt,
      tank: newest.tank,
      phase: newest.phase,
      species: newest.species,
      detectionStatus: newest.suspectedPathology
    } : null,
    alertsActive: cases.length,
    pendingValidation: pending,
    sensors: {
      temperature: newest?.temperature ?? null,
      ph: newest?.ph ?? null,
      oxygen: newest?.oxygen ?? null,
      status: warningSensor
    },
    device: {
      online: true,
      lastCommunication: newest?.capturedAt ?? null,
      cameraOk: Boolean(newest?.image),
      sensorsOk: warningSensor === 'OK'
    }
  };
};

const severityTone = (severity: Severity) => {
  if (severity === 'critical') return 'aql-lab-critical';
  if (severity === 'high') return 'aql-lab-warning';
  if (severity === 'medium') return 'border-amber-300/55 bg-amber-300/10 text-amber-100';
  return 'aql-lab-normal';
};

const statusTone = (status?: string | null) => {
  const value = String(status ?? '').toLowerCase();
  if (value.includes('alert')) return 'aql-lab-critical';
  if (value.includes('aten')) return 'aql-lab-warning';
  return 'aql-lab-normal';
};

