const slugify = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');

const liveFeedPathForCameraCode = (code: string | null) =>
  code ? `live/${code}/feed.jpg` : null;

const trainingBurstPathForCameraCode = (code: string | null) =>
  code ? `live/${code}/training` : null;

const pickString = (...values: unknown[]) => {
  const found = values.find((value) => value !== undefined && value !== null && value !== '');
  return found == null ? null : String(found);
};

const pickNumber = (...values: unknown[]) => {
  const found = values.find((value) => value !== undefined && value !== null && value !== '');
  if (found == null) return null;
  const parsed = typeof found === 'number' ? found : Number(String(found));
  return Number.isFinite(parsed) ? parsed : null;
};

const payloadNumber = (value: unknown) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = typeof value === 'number' ? value : Number(String(value).replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
};

