async function saveRuntimeFrameIntervalConfig(key: DatasetKey, payload: Record<string, any>) {
  const frameIntervalMs = payload.frame_interval_ms;
  if (!Number.isFinite(Number(frameIntervalMs))) return;
  if (key !== 'kits' && key !== 'cameras') return;

  const clientId = String(payload.client_id ?? '').trim();
  if (!clientId) return;

  const runtimeRow = {
    client_id: clientId,
    project_id: payload.project_id || null,
    location_id: payload.location_id || null,
    zone_id: payload.zone_id || null,
    kit_id: key === 'kits' ? payload.kit_id : payload.kit_id || null,
    camera_id: key === 'cameras' ? payload.camera_id : null,
    device_id: null,
    config_key: key === 'cameras' && payload.camera_code
      ? `camera.${payload.camera_code}.frame_interval_ms`
      : 'frame_interval_ms',
    config_value: { value: Number(frameIntervalMs) },
    is_enabled: true
  };

  const { error } = await withQueryTimeout(
    (signal) => supabase
      .from('aql_device_runtime_configs')
      .upsert(runtimeRow, {
        onConflict: 'client_id,project_id,location_id,zone_id,kit_id,device_id,camera_id,config_key'
      })
      .abortSignal(signal),
    'Timed out while saving live runtime config.'
  );

  if (error) {
    console.warn('AQL Vision: could not save live runtime config', error);
  }
}

export async function loadConfigurationDataset(accessToken?: string | null): Promise<{ data: AqlConfigurationDataset; source: 'supabase' | 'mixed'; warning?: string }> {
  const keys = Object.keys(tableMap) as DatasetKey[];
  const warnings: string[] = [];
  const result = { ...EMPTY_CONFIGURATION_DATASET } as AqlConfigurationDataset;
  const db = configurationClient(accessToken);
  let supabaseCount = 0;

  await Promise.all(
    keys.map(async (key) => {
      try {
        result[key] = await fetchTable(key, db);
        supabaseCount += 1;
      } catch (error: any) {
        warnings.push(`${tableMap[key]}: ${error?.message ?? 'unavailable'}`);
      }
    })
  );

  if (result.users.length) {
    try {
      const clientAccess = await fetchUserClientAccess(db);
      result.users = result.users.map((user) => {
        const linkedClientIds = clientAccess[user.user_id] ?? [];
        const clientIds = Array.from(new Set([
          ...linkedClientIds,
          ...(user.client_id ? [user.client_id] : [])
        ]));
        return {
          ...user,
          client_ids: clientIds,
          client_id: user.client_id ?? clientIds[0] ?? null
        };
      });
    } catch (error: any) {
      if (!missingRelationError(error, 'aql_user_clients')) {
        console.warn('AQL Vision: could not load user client access', error);
      }
    }

    try {
      const projectAccess = await fetchUserProjectAccess(db);
      result.users = result.users.map((user) => {
        const linkedProjectIds = projectAccess[user.user_id] ?? [];
        const projectIds = Array.from(new Set([
          ...linkedProjectIds,
          ...(user.project_id ? [user.project_id] : [])
        ]));
        return {
          ...user,
          project_ids: projectIds,
          project_id: projectIds[0] ?? null,
          project_scope: projectIds.length ? 'specific' : 'all'
        };
      });
    } catch (error: any) {
      if (!missingRelationError(error, 'aql_user_projects')) {
        console.warn('AQL Vision: could not load user project access', error);
      }
    }
  }

  const source = supabaseCount === keys.length ? 'supabase' : 'mixed';

  return {
    data: result,
    source,
    warning: warnings.length ? warnings.join(' | ') : undefined
  };
}

export async function saveConfigurationRecord<K extends DatasetKey>(
  key: K,
  item: AqlConfigurationDataset[K][number]
): Promise<AqlConfigurationDataset[K][number]> {
  const table = tableMap[key];
  const idKey = idKeyMap[key];
  let payload = serializePayload(key, item);
  const requestedFrameIntervalMs = (payload as Record<string, any>).frame_interval_ms;
  const idValue = String((payload as Record<string, any>)[idKey] ?? '');

  let { error: writeError } = await withQueryTimeout(
    (signal) => supabase.from(table).upsert(payload, { onConflict: idKey }).abortSignal(signal),
    `Timed out while saving ${table}.`
  );

  if (writeError && missingColumnError(writeError, 'frame_interval_ms') && (key === 'kits' || key === 'cameras')) {
    const retryPayload = { ...(payload as Record<string, any>) };
    delete retryPayload.frame_interval_ms;
    payload = retryPayload as typeof payload;
    const retry = await withQueryTimeout(
      (signal) => supabase.from(table).upsert(payload, { onConflict: idKey }).abortSignal(signal),
      `Timed out while saving ${table}.`
    );
    writeError = retry.error;
  }

  if (writeError) throw writeError;

  if ((key === 'kits' || key === 'cameras') && Number.isFinite(Number(requestedFrameIntervalMs))) {
    await saveRuntimeFrameIntervalConfig(key, {
      ...(payload as Record<string, any>),
      frame_interval_ms: requestedFrameIntervalMs
    });
  }

  const { data, error: readError } = await withQueryTimeout(
    (signal) => supabase.from(table).select('*').eq(idKey, idValue).abortSignal(signal).maybeSingle(),
    `Timed out while loading the saved ${table} record.`
  );

  if (readError) throw readError;
  if (!data) {
    throw new Error(`Saved ${table}, but could not read the record back. Check table policies for select access.`);
  }

  const saved = normalizers[key](data) as AqlConfigurationDataset[K][number];
  if ((key === 'kits' || key === 'cameras') && Number.isFinite(Number(requestedFrameIntervalMs))) {
    (saved as Record<string, any>).frame_interval_ms = Number(requestedFrameIntervalMs);
  }
  if (key === 'cameras') {
    await ensureCameraLiveFolder(saved as AqlCamera).catch((error) => {
      console.warn('AQL Vision: could not create live camera folder', error);
    });
  }

  return saved;
}

export async function saveConfigurationUserAccess(
  item: AqlUserAccess,
  mode: 'create' | 'edit',
  access: ConfigurationPortalAccess
): Promise<AqlUserAccess> {
  const email = String(item.email ?? '').trim().toLowerCase();
  const mobilePhone = String(item.mobile_phone ?? '').replace(/[\s().-]/g, '');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error('Please enter a valid email address before creating the user.');
  }
  if (mobilePhone && !/^\+[1-9]\d{7,14}$/.test(mobilePhone)) {
    throw new Error('Please enter the mobile phone in international format, for example +351912345678.');
  }

  try {
    const response = await fetch(`${functionsBaseUrl}/config-manage-user`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        apikey: publicAnonKey,
        Authorization: `Bearer ${access.accessToken}`
      },
      body: JSON.stringify({
        operation: mode,
        accessMode: access.mode,
        clientSlug: access.clientSlug,
        redirectTo: getCurrentAuthRedirectUrl(),
        user: serializePayload('users', { ...item, email, mobile_phone: mobilePhone || null })
      })
    });

    const responseText = await response.text();
    let payload: any = {};
    try {
      payload = responseText ? JSON.parse(responseText) : {};
    } catch {
      payload = {};
    }
    if (!response.ok) {
      throw new Error(payload?.error ?? (responseText || `Failed to provision user. HTTP ${response.status}`));
    }

    return normalizeUser(payload.user);
  } catch (error: any) {
    if (error instanceof TypeError) {
      throw new Error('Could not reach the user provisioning function. Check that the Supabase Edge Function `config-manage-user` is deployed and reachable.');
    }
    throw error;
  }
}

