const isMissingRpcError = (error: any) =>
  error?.code === 'PGRST202' ||
  String(error?.message ?? '').toLowerCase().includes('could not find the function');

const deleteOperationalCascade = async ({
  locationIds = [],
  zoneIds = [],
  kitIds = [],
  cameraIds = [],
  sensorIds = [],
  deviceIds = []
}: {
  locationIds?: string[];
  zoneIds?: string[];
  kitIds?: string[];
  cameraIds?: string[];
  sensorIds?: string[];
  deviceIds?: string[];
}) => {
  const zoneIdsFromLocations = await selectIdsIn('aql_zones', 'zone_id', 'location_id', locationIds);
  const allZoneIds = Array.from(new Set([...zoneIds, ...zoneIdsFromLocations]));

  const [kitIdsFromLocations, kitIdsFromZones] = await Promise.all([
    selectIdsIn('aql_kits', 'kit_id', 'location_id', locationIds),
    selectIdsIn('aql_kits', 'kit_id', 'zone_id', allZoneIds)
  ]);
  const allKitIds = Array.from(new Set([...kitIds, ...kitIdsFromLocations, ...kitIdsFromZones]));

  const [cameraIdsByKit, cameraIdsByZone, sensorIdsByKit, sensorIdsByZone, deviceIdsByKit] = await Promise.all([
    selectIdsIn('aql_cameras', 'camera_id', 'kit_id', allKitIds),
    selectIdsIn('aql_cameras', 'camera_id', 'zone_id', allZoneIds),
    selectIdsIn('aql_sensors', 'sensor_id', 'kit_id', allKitIds),
    selectIdsIn('aql_sensors', 'sensor_id', 'zone_id', allZoneIds),
    selectIdsIn('aql_devices', 'device_id', 'kit_id', allKitIds)
  ]);
  const allCameraIds = Array.from(new Set([...cameraIds, ...cameraIdsByKit, ...cameraIdsByZone]));
  const allSensorIds = Array.from(new Set([...sensorIds, ...sensorIdsByKit, ...sensorIdsByZone]));
  const sensorDeviceIds = await selectIdsIn('aql_sensors', 'device_id', 'sensor_id', allSensorIds);
  const allDeviceIds = Array.from(new Set([...deviceIds, ...deviceIdsByKit, ...sensorDeviceIds]));
  const captureIds = await selectIdsIn('aql_vision_captures', 'capture_id', 'device_id', allDeviceIds);
  const detectionIds = await selectIdsIn('aql_detections', 'detection_id', 'capture_id', captureIds);
  const [alertIdsByDevice, alertIdsByCamera, alertIdsByZone] = await Promise.all([
    selectIdsIn('aql_alerts', 'alert_id', 'device_id', allDeviceIds),
    selectIdsIn('aql_alerts', 'alert_id', 'camera_id', allCameraIds),
    selectIdsIn('aql_alerts', 'alert_id', 'zone_id', allZoneIds)
  ]);
  const alertIds = Array.from(new Set([...alertIdsByDevice, ...alertIdsByCamera, ...alertIdsByZone]));

  await deleteIn('aql_cases', 'detection_id', detectionIds);
  await deleteIn('aql_cases', 'source_capture_id', captureIds);
  await deleteIn('aql_cases', 'alert_id', alertIds);
  await deleteIn('aql_growth_measurements', 'capture_id', captureIds);
  await deleteIn('aql_growth_measurements', 'detection_id', detectionIds);
  await deleteIn('aql_growth_calibrations', 'kit_id', allKitIds);
  await deleteIn('aql_growth_calibrations', 'camera_id', allCameraIds);
  await deleteIn('aql_growth_calibrations', 'device_id', allDeviceIds);
  await deleteIn('aql_detections', 'detection_id', detectionIds);
  await deleteIn('aql_vision_captures', 'capture_id', captureIds);
  await deleteIn('aql_sensor_readings', 'device_id', allDeviceIds);
  await deleteIn('aql_sensor_readings', 'sensor_id', allSensorIds).catch(() => undefined);
  await deleteIn('aql_alerts', 'alert_id', alertIds);
  await deleteIn('aql_sensors', 'sensor_id', allSensorIds);
  await deleteIn('aql_devices', 'device_id', allDeviceIds);
  await deleteIn('aql_cameras', 'camera_id', allCameraIds);
  await deleteIn('aql_kits', 'kit_id', allKitIds);
  await deleteIn('aql_zones', 'zone_id', allZoneIds);
  await deleteIn('aql_locations', 'location_id', locationIds);
};

